scripts:
function showToast(title, message){
  const old =
    document.getElementById("app-toast");
  if(old){
    old.remove();
  }
  const el =
    document.createElement("div");
  el.id = "app-toast";
  el.className =
    "toast fixed bottom-5 right-5 z-[60] " +
    "max-w-sm rounded-xl bg-[var(--forest)] " +
    "text-white shadow-2xl p-4";
  el.innerHTML = `
    <p class="font-display font-semibold">
      ${title}
    </p>
    <p class="text-xs text-white/70 mt-1">
      ${message}
    </p>
  `;
  document.body.appendChild(el);
  setTimeout(() => {
    el.remove();
  }, 3500);
}
function daysFromNow(n){
  const d = new Date();
  d.setDate(
    d.getDate() + n
  );
  return d;
}
function fmtDate(d){
  return new Date(d).toLocaleDateString(
    undefined,
    {
      month:"short",
      day:"numeric"
    }
  );
}
function daysUntil(d){
  const target =
    new Date(d);
  const today =
    new Date();
  target.setHours(
    0,0,0,0
  );
  today.setHours(
    0,0,0,0
  );
  return Math.round(
    (target - today) /
    86400000
  );
}
const student = {
  name:"Lakpa Tsering",
  id:"20481-B",
  goal:24
};
const genres = [
  "All",
  "Fiction",
  "Science",
  "History",
  "Poetry",
  "Reference"
];
const defaultCatalog = [
  {
    id:1,
    title:"The Sympathizer",
    author:"Viet Thanh Nguyen",
    genre:"Fiction",
    copies:3
  },
  {
    id:2,
    title:"Braiding Sweetgrass",
    author:"Robin Wall Kimmerer",
    genre:"Science",
    copies:0
  },
  {
    id:3,
    title:"The Wretched of the Earth",
    author:"Frantz Fanon",
    genre:"History",
    copies:2
  },
  {
    id:4,
    title:"Citizen: An American Lyric",
    author:"Claudia Rankine",
    genre:"Poetry",
    copies:1
  },
  {
    id:5,
    title:"A Brief History of Time",
    author:"Stephen Hawking",
    genre:"Science",
    copies:4
  },
  {
    id:6,
    title:"The Elements of Style",
    author:"Strunk & White",
    genre:"Reference",
    copies:6
  },
  {
    id:7,
    title:"Beloved",
    author:"Toni Morrison",
    genre:"Fiction",
    copies:0
  },
  {
    id:8,
    title:"Sapiens",
    author:"Yuval Noah Harari",
    genre:"History",
    copies:2
  },
  {
    id:9,
    title:"Postcolonial Love Poem",
    author:"Natalie Diaz",
    genre:"Poetry",
    copies:3
  }
];
const defaultBorrowed = [
  {
    id:101,
    title:"Pale Fire",
    author:"Vladimir Nabokov",
    due:daysFromNow(2).toISOString(),
    renewals:1
  },
  {
    id:102,
    title:"The Order of Time",
    author:"Carlo Rovelli",
    due:daysFromNow(-1).toISOString(),
    renewals:0
  },
  {
    id:103,
    title:"Ways of Seeing",
    author:"John Berger",
    due:daysFromNow(9).toISOString(),
    renewals:2
  }
];
const STORAGE_KEY =
  "icfai-library-dashboard-v3";
function loadState(){
  try{
    return JSON.parse(
      localStorage.getItem(
        STORAGE_KEY
      ) || "null"
    );
  }catch{
    return null;
  }
}
const savedState =
  loadState();
let catalog =
  savedState?.catalog ||
  structuredClone(
    defaultCatalog
  );
let borrowed =
  (
    savedState?.borrowed ||
    structuredClone(
      defaultBorrowed
    )
  ).map(book => ({
    ...book,
    due:new Date(book.due)
  }));
let booksReadThisYear =
  savedState?.booksReadThisYear ??
  14;
let holds =
  savedState?.holds ||
  [
    {
      id:7,
      title:"Beloved",
      author:"Toni Morrison",
      position:2,
      status:"Waiting"
    }
  ];
let activity =
  savedState?.activity ||
  [
    {
      title:"Returned a library item",
      detail:"Your account activity was updated.",
      time:"Today"
    },
    {
      title:"Renewal available",
      detail:"Pale Fire has 1 renewal remaining.",
      time:"Yesterday"
    },
    {
      title:"Hold updated",
      detail:"Beloved is currently 2nd in the queue.",
      time:"Aug 12"
    },
    {
      title:"Reading goal progress",
      detail:"14 books completed toward your 2026 goal.",
      time:"Aug 10"
    }
  ];
const notices = [
  {
    text:"Reading Room B closed for renovation through Sept 3.",
    tag:"Facilities"
  },
  {
    text:"Your hold on “Beloved” — 2nd in queue.",
    tag:"Holds"
  },
  {
    text:"Fall library orientation begins Sept 15.",
    tag:"Announcement"
  }
];
const recommendations = [
  {
    title:"The Left Hand of Darkness",
    author:"Ursula K. Le Guin",
    genre:"Fiction",
    reason:"A strong choice if you enjoy thoughtful fiction."
  },
  {
    title:"Cosmos",
    author:"Carl Sagan",
    genre:"Science",
    reason:"Explore science through clear, engaging storytelling."
  },
  {
    title:"The Silk Roads",
    author:"Peter Frankopan",
    genre:"History",
    reason:"A broad historical perspective across regions and eras."
  }
];
function saveState(){
  try{
    localStorage.setItem(
      STORAGE_KEY,
      JSON.stringify({
        catalog,
        borrowed:
          borrowed.map(book => ({
            ...book,
            due:
              new Date(
                book.due
              ).toISOString()
          })),
        booksReadThisYear,
        activity,
        holds
      })
    );
  }catch(e){}
}
document.getElementById(
  "student-name"
).textContent =
  student.name;
document.getElementById(
  "student-id"
).textContent =
  "CARD ID " +
  student.id;
document.getElementById(
  "greet-name"
).textContent =
  student.name.split(" ")[0];
document.getElementById(
  "today-line"
).textContent =
  new Date().toLocaleDateString(
    undefined,
    {
      weekday:"long",
      month:"long",
      day:"numeric",
      year:"numeric"
    }
  );
document.getElementById(
  "logout-btn"
).addEventListener(
  "click",
  () => {
    if(
      confirm(
        "Are you sure you want to logout?"
      )
    ){
      showToast(
        "Logged out",
        "You have been logged out successfully."
      );
      setTimeout(
        () => {
          window.location.href =
            "/?login=1";
        },
        1000
      );
    }
  }
);
function renderStats(){
  const dueSoon =
    borrowed.filter(
      book =>
        daysUntil(book.due) <= 3
    ).length;
  const overdue =
    borrowed.filter(
      book =>
        daysUntil(book.due) < 0
    ).length;
  const stats = [
    {
      label:"Checked Out",
      value:borrowed.length,
      sub:"of 5 allowed"
    },
    {
      label:"Due Soon",
      value:dueSoon,
      sub:"within 3 days"
    },
    {
      label:"Overdue",
      value:overdue,
      sub:
        overdue === 1
          ? "item needs attention"
          : "items need attention"
    },
    {
      label:"Read This Year",
      value:booksReadThisYear,
      sub:
        "toward goal of " +
        student.goal
    }
  ];
  document.getElementById(
    "stats-row"
  ).innerHTML =
    stats.map(stat => `
      <div class="index-card index-card-pad rounded-sm p-5 hover:shadow-md transition">
        <p class="font-mono text-[9px] uppercase tracking-[0.2em] text-[var(--brass)] font-medium"> ${stat.label} </p>
        <p class="font-display text-2xl font-bold mt-3"> ${stat.value} </p>
        <p class="text-xs text-[var(--ink)]/40 mt-2"> ${stat.sub} </p>
      </div>
    `).join("");
}
function renderBorrowed(){
  document.getElementById(
    "borrowed-count-label"
  ).textContent =
    borrowed.length +
    " item" +
    (
      borrowed.length === 1
        ? ""
        : "s"
    );
  const list =
    document.getElementById(
      "borrowed-list"
    );
  if(
    borrowed.length === 0
  ){
    list.innerHTML = `
      <div class="index-card-pad p-8 text-sm text-[var(--ink)]/50 text-center">
        Nothing checked out —
        browse the catalog below
        to find your next read.
      </div>
    `;
    return;
  }
  list.innerHTML =
    borrowed.map(
      (book,index) => {
        const remaining =
          daysUntil(book.due);
        const overdue =
          remaining < 0;
        const soon =
          remaining >= 0 &&
          remaining <= 3;
        const statusColor =
          overdue
            ? "text-red-700"
            : soon
              ? "text-[var(--brass)]"
              : "text-[var(--forest-2)]";
        const statusText =
          overdue
            ? `${Math.abs(remaining)}d overdue`
            : remaining === 0
              ? "due today"
              : `${remaining}d left`;
        return `
          <div class=" index-card-pad p-5 flex flex-col sm:flex-row sm:items-center justify-between gap-4 ${index > 0 ? "rule-dashed" : ""} hover:bg-[var(--ivory)]/30 transition">
            <div class="min-w-0">
              <p class="font-display font-semibold text-base leading-snug"> ${book.title} </p>
              <p class="text-xs text-[var(--ink)]/50 mt-0.5"> ${book.author} </p>
              <p class="font-mono text-[9px] mt-2 ${statusColor}"> DUE ${fmtDate(book.due).toUpperCase()} · ${statusText.toUpperCase()} </p>
            </div>
            <div class="flex items-center gap-2 shrink-0">
              <button
                data-id="${book.id}"
                class="
                  renew-btn
                  font-mono
                  text-[10px]
                  uppercase
                  tracking-wider
                  font-medium
                  border
                  border-[var(--line)]
                  rounded-sm
                  px-3 py-1.5
                  hover:border-[var(--brass-2)]
                  hover:text-[var(--brass)]
                  active:scale-95
                  transition
                  ${
                    book.renewals >= 2
                      ? "opacity-30 cursor-not-allowed"
                      : ""
                  }"
                ${
                  book.renewals >= 2
                    ? "disabled"
                    : ""
                }>
                Renew (${2 - book.renewals} left)
              </button>
              <button
                data-id="${book.id}"
                class="
                  return-btn
                  font-mono
                  text-[10px]
                  uppercase
                  tracking-wider
                  font-medium
                  text-[var(--ink)]/40
                  hover:text-red-600
                  active:scale-95
                  transition">
                Return
              </button>
            </div>
          </div>
        `;
      }
    ).join("");
  list.querySelectorAll(
    ".renew-btn"
  ).forEach(button => {
    button.addEventListener(
      "click",
      () => {
        const id =
          Number(
            button.dataset.id
          );
        const book =
          borrowed.find(
            item =>
              item.id === id
          );
        if(
          !book ||
          book.renewals >= 2
        ){
          return;
        }
        book.renewals += 1;
        book.due =
          daysFromNow(14);
        addActivity(
          "Book renewed",
          `${book.title} is now due in 14 days.`,
          "↻"
        );
        renderBorrowed();
        renderStats();
        saveState();
        showToast(
          "Book renewed",
          `${book.title} is due in 14 days.`
        );
      }
    );
  });
  list.querySelectorAll(
    ".return-btn"
  ).forEach(button => {
    button.addEventListener(
      "click",
      () => {
        const id =
          Number(
            button.dataset.id
          );
        const book =
          borrowed.find(
            item =>
              item.id === id
          );
        if(!book){
          return;
        }
        borrowed =
          borrowed.filter(
            item =>
              item.id !== id
          );
        booksReadThisYear += 1;
        addActivity(
          "Book returned",
          `${book.title} was returned successfully.`,
          "✓"
        );
        renderBorrowed();
        renderStats();
        renderGoal();
        renderRecommendations();
        saveState();
        showToast(
          "Book returned",
          `${book.title} has been added to your reading progress.`
        );
      }
    );
  });
}
function renderGoal(){
  const percentage =
    Math.min(
      100,
      Math.round(
        (
          booksReadThisYear /
          student.goal
        ) * 100
      )
    );
  document.getElementById(
    "goal-count"
  ).textContent =
    `${booksReadThisYear} / ${student.goal}`;
  document.getElementById(
    "goal-pct"
  ).textContent =
    percentage + "%";
  document.getElementById(
    "goal-bar"
  ).style.width =
    percentage + "%";
  document.getElementById(
    "card-progress-ring"
  ).style.setProperty(
    "--progress",
    percentage + "%"
  );
  document.getElementById(
    "card-progress-text"
  ).textContent =
    `${booksReadThisYear}/${student.goal}`;
}
function renderNotices(){
  document.getElementById(
    "notices-list"
  ).innerHTML =
    notices.map(
      notice => `
        <li
          class="flex gap-2 py-0.5">
          <span
            class="
              font-mono
              text-[8px]
              uppercase
              tracking-wider
              font-medium
              text-[var(--brass)]
              border
              border-[var(--line)]
              rounded-sm
              px-2 py-1
              h-fit
              shrink-0">
            ${notice.tag}
          </span>
          <span
            class="
              text-[var(--ink)]/70
              text-sm
              leading-relaxed">
            ${notice.text}
          </span>
        </li>
      `
    ).join("");
}
let activeGenre =
  "All";
function renderFilters(){
  document.getElementById(
    "genre-filters"
  ).innerHTML =
    genres.map(
      genre => `
        <button
          data-genre="${genre}"
          class="
            genre-btn
            font-mono
            text-[10px]
            uppercase
            tracking-wider
            font-medium
            px-4 py-2
            rounded-full
            border
            shrink-0
            transition
            ${
              genre === activeGenre
                ? "bg-[var(--forest)] text-white border-[var(--forest)]"
                : "bg-[var(--card)] border-[var(--line)] hover:border-[var(--brass-2)]"
            }">
          ${genre}
        </button>
      `
    ).join("");
  document.querySelectorAll(
    ".genre-btn"
  ).forEach(button => {
    button.addEventListener(
      "click",
      () => {
        activeGenre =
          button.dataset.genre;
        renderFilters();
        renderCatalog();
      }
    );
  });
}
let catalogSort =
  "title";
function renderCatalog(){
  const query =
    (
      document.getElementById(
        "search-input"
      ).value || ""
    )
    .toLowerCase()
    .trim();
  let filtered =
    catalog.filter(
      book => {
        const genreMatch =
          activeGenre === "All" ||
          book.genre === activeGenre;
        const queryMatch =
          !query ||
          book.title
            .toLowerCase()
            .includes(query) ||
          book.author
            .toLowerCase()
            .includes(query);
        return (
          genreMatch &&
          queryMatch
        );
      }
    );
  filtered.sort(
    (a,b) => {
      if(
        catalogSort === "author"
      ){
        return a.author.localeCompare(
          b.author
        );
      }
      if(
        catalogSort === "availability"
      ){
        return (
          b.copies - a.copies ||
          a.title.localeCompare(
            b.title
          )
        );
      }
      return a.title.localeCompare(
        b.title
      );
    }
  );
  const grid =
    document.getElementById(
      "catalog-grid"
    );
  if(!filtered.length){
    grid.innerHTML = `
      <div
        class="
          col-span-full
          index-card
          rounded-sm
          p-8
          text-sm
          text-[var(--ink)]/50
          text-center">
        No titles match
        ${
          query
            ? `“${query.replace(
                /</g,
                "&lt;"
              )}”`
            : "your filters"
        }.
        <br>
        Try another search
        or section.
      </div>
    `;
    return;
  }
  grid.innerHTML =
    filtered.map(
      book => {
        const available =
          book.copies > 0;
        const alreadyBorrowed =
          borrowed.some(
            item =>
              item.title ===
              book.title
          );
        const alreadyOnHold =
          holds.some(
            hold =>
              hold.id ===
              book.id
          );
        let buttonText;
        if(alreadyBorrowed){
          buttonText =
            "Checked out";
        }
        else if(
          !available &&
          alreadyOnHold
        ){
          buttonText =
            "On hold";
        }
        else if(available){
          buttonText =
            "Check out";
        }
        else{
          buttonText =
            "Place hold";
        }
        return `
          <div
            class="
              index-card
              index-card-pad
              catalog-card
              rounded-sm
              p-5
              flex
              flex-col
              justify-between
              hover:shadow-md
              transition">
            <div>
              <p
                class="
                  font-mono
                  text-[9px]
                  uppercase
                  tracking-[0.2em]
                  text-[var(--brass)]
                  font-medium">
                ${book.genre}
              </p>
              <p
                class="
                  font-display
                  font-semibold
                  mt-2
                  leading-snug
                  text-base">
                ${book.title}
              </p>
              <p
                class="
                  text-xs
                  text-[var(--ink)]/50
                  mt-1">
                ${book.author}
              </p>
              <div class="mt-4">
                <div
                  class="
                    flex
                    justify-between
                    text-[8px]
                    font-mono
                    text-[var(--ink)]/40
                    mb-1">
                  <span>
                    AVAILABILITY
                  </span>
                  <span>
                    ${book.copies}/6
                  </span>
                </div>
                <div class="availability-bar">
                  <div
                    class="availability-fill"
                    style="
                      width:${Math.min(
                        100,
                        (book.copies / 6) *
                        100
                      )}%
                    ">
                  </div>
                </div>
              </div>
            </div>
            <div
              class="
                flex
                items-center
                justify-between
                mt-5
                gap-3">
              <p
                class="
                  font-mono
                  text-[9px]
                  font-medium
                  ${
                    available
                      ? "text-[var(--forest-2)]"
                      : "text-red-600"
                  }">
                ${
                  available
                    ? book.copies +
                      " AVAILABLE"
                    : "ALL COPIES OUT"
                }
              </p>
              <button
                data-id="${book.id}"
                class="
                  action-btn
                  shrink-0
                  font-mono
                  text-[10px]
                  uppercase
                  tracking-wider
                  font-medium
                  border
                  border-[var(--line)]
                  rounded-sm
                  px-3 py-1.5
                  hover:border-[var(--brass-2)]
                  hover:text-[var(--brass)]
                  active:scale-95
                  transition
                  ${
                    alreadyBorrowed ||
                    (!available &&
                      alreadyOnHold)
                      ? "opacity-50 cursor-not-allowed"
                      : ""
                  }"
                ${
                  alreadyBorrowed ||
                  (!available &&
                    alreadyOnHold)
                    ? "disabled"
                    : ""
                }>
                ${buttonText}
              </button>
            </div>
          </div>
        `;
      }
    ).join("");
  grid.querySelectorAll(
    ".action-btn"
  ).forEach(button => {
    button.addEventListener(
      "click",
      () => {
        const book =
          catalog.find(
            item =>
              item.id ===
              Number(
                button.dataset.id
              )
          );
        if(!book){
          return;
        }
        if(book.copies > 0){
          if(
            borrowed.length >= 5
          ){
            showToast(
              "Checkout limit reached",
              "You can have up to 5 books checked out at once."
            );
            return;
          }
          if(
            borrowed.some(
              item =>
                item.title ===
                book.title
            )
          ){
            showToast(
              "Already checked out",
              "This title is already on your account."
            );
            return;
          }
          book.copies -= 1;
          borrowed.push({
            id:1000 + book.id,
            title:book.title,
            author:book.author,
            due:daysFromNow(14),
            renewals:0
          });
          addActivity(
            "Book checked out",
            `${book.title} is now on your account.`,
            "✓"
          );
          renderBorrowed();
          renderStats();
          renderCatalog();
          saveState();
          showToast(
            "Checked out",
            `${book.title} is due in 14 days.`
          );
          return;
        }
        if(
          !holds.some(
            hold =>
              hold.id ===
              book.id
          )
        ){
          holds.push({
            id:book.id,
            title:book.title,
            author:book.author,
            position:
              holds.length + 1,
            status:"Waiting"
          });
          addActivity(
            "Hold placed",
            `You joined the queue for ${book.title}.`,
            "▱"
          );
          saveState();
          renderCatalog();
          showToast(
            "Hold placed",
            `${book.title} was added to My Holds.`
          );
        }
        else{
          showToast(
            "Already on hold",
            `${book.title} is already in My Holds.`
          );
        }
      }
    );
  });
}
document.getElementById(
  "search-input"
).addEventListener(
  "input",
  renderCatalog
);
document.getElementById(
  "sort-select"
).addEventListener(
  "change",
  event => {
    catalogSort =
      event.target.value;
    renderCatalog();
  }
);
function renderActivity(){
  const container =
    document.getElementById(
      "activity-list"
    );
  if(!activity.length){
    container.innerHTML = `
      <div
        class="empty-state
               text-sm
               text-[var(--ink)]/45">
        No recent activity.
      </div>
    `;
    return;
  }
  container.innerHTML =
    activity
      .slice(0,6)
      .map(
        item => `
          <div
            class="activity-item">
            <span
              class="activity-dot">
            </span>
            <div
              class="min-w-0
                     flex-1">
              <div
                class="flex
                       justify-between
                       gap-3">
                <p
                  class="
                    font-display
                    font-semibold
                    text-sm">
                  ${item.icon}
                  ${item.title}
                </p>
                <span
                  class="
                    font-mono
                    text-[8px]
                    text-[var(--ink)]/35
                    shrink-0">
                  ${item.time}
                </span>
              </div>
              <p
                class="
                  text-xs
                  text-[var(--ink)]/50
                  mt-1">
                ${item.detail}
              </p>
            </div>
          </div>
        `
      )
      .join("");
}
function addActivity(
  title,
  detail,
  icon="•"
){
  activity.unshift({
    icon,
    title,
    detail,
    time:"Just now"
  });
  renderActivity();
}
function renderRecommendations(){
  const container =
    document.getElementById(
      "recommendations-grid"
    );
  container.innerHTML =
    recommendations
      .map(
        (book,index) => `
          <div
            class="
              index-card
              p-5
              recommend-card">
            <div class="book-cover">
              ${String(
                index + 1
              ).padStart(2,"0")}
            </div>
            <div class=" min-w-0 flex-1 flex flex-col">
              <span class=" mini-badge text-[var(--brass)]"> ${book.genre} </span>
              <p class=" font-display font-semibold text-base mt-2 leading-snug"> ${book.title} </p>
              <p class=" text-xs text-[var(--ink)]/50 mt-1"> ${book.author} </p>
              <p class=" text-xs text-[var(--ink)]/45 mt-auto pt-3"> ${book.reason} </p>
            </div>
          </div>
        `
      )
      .join("");
}
